# Imports & app setup
from fastapi import FastAPI, HTTPException
# FastAPI       -> the class used to create the app instance
# HTTPException -> used to return proper error responses (like Flask's jsonify+status)

from pydantic import BaseModel
# BaseModel -> base class for defining data schemas with type validation

from typing import Optional
# Optional[str] means "a str, or None" — used for fields that aren't required

app = FastAPI(title="FastAPI CRUD Blueprint")
# Creates the app instance. `title` shows up on the auto-generated /docs page.
'''
Real-world difference: Same as Flask — production apps 
use an app-factory pattern, and often split routers into 
separate files using APIRouter() instead of one flat app object.
'''

# Schemas (this is FastAPI's biggest structural difference from Flask)
class Item(BaseModel):
    name: str
    # Required field. If missing or wrong type, FastAPI auto-rejects the
    # request with a 422 error — before your function body even runs.
    description: Optional[str] = ""
    # Optional field with a default value of "" if the client doesn't send it.

class ItemUpdate(BaseModel):
    name: Optional[str] = None
    description: Optional[str] = None
    # Both optional and default to None, since PUT/update may only change
    # one field at a time.
"""
Why this matters: In Flask, you manually wrote if not data or "name" 
not in data: return error. In FastAPI, this whole block is replaced by 
declaring item: Item as a function parameter — validation happens 
automatically via Pydantic.

Real-world difference: Production schemas add field constraints 
(Field(min_length=1, max_length=100)), custom validators (@validator), 
and often separate models for input vs. output 
(e.g., a UserCreate model with a password field vs. 
a UserResponse model that excludes it).
"""

# In-memory database — identical concept to Flask
"""
items = {
    1: {"id": 1, "name": "Item One", "description": "First sample item"},
    2: {"id": 2, "name": "Item Two", "description": "Second sample item"},
}
next_id = 3
"""

items = {}
next_id = 1

"""
Same explanation and same real-world caveat as Flask — a real project 
replaces this with a database via SQLModel/SQLAlchemy, 
with IDs auto-generated by the DB.
"""
# Health check
@app.get("/")
# Decorator directly encodes both the path AND the HTTP method (@app.get, not
# @app.route(..., methods=["GET"])) — FastAPI has a separate decorator per verb.
def health_check():
    return {"status": "ok", "message": "FastAPI CRUD API is running"}
    # No jsonify(), no status code specified — defaults to 200 automatically,
    # and the dict is auto-serialized to JSON.

# GET all items
@app.get("/items")
def get_items():
    return list(items.values())
    # Returning a list of dicts — FastAPI serializes this into a JSON array,
    # same as jsonify(list(...)) did in Flask, just without the explicit call.
'''
Real-world difference: Same as Flask — pagination 
(skip/limit query params) instead of returning everything.
'''
# GET single item
@app.get("/items/{item_id}")
# {item_id} in the path is matched to the function parameter below.
def get_item(item_id: int):
    # The `: int` type hint does double duty:
    #  1. FastAPI auto-converts the URL string to an int
    #  2. If the value isn't a valid int (e.g. /items/abc), FastAPI auto-returns
    #     a 422 error WITHOUT you writing any validation code.
    item = items.get(item_id)
    if not item:
        raise HTTPException(status_code=404, detail="Item not found")
        # raise, not return — HTTPException is caught by FastAPI's exception
        # handler internally, which converts it into a proper JSON error response
        # like {"detail": "Item not found"} with the given status code.
    return item
'''
Compare to Flask: Flask used <int:item_id> in the route string for 
the same type-casting behavior; FastAPI does it via the Python type 
hint instead — this is the core FastAPI philosophy: type hints drive 
behavior, not decorator syntax.
'''
# POST — create item
@app.post("/items", status_code=201)
# status_code=201 sets the *default success* status code for this whole route,
# so you don't need to specify it in every return statement (unlike Flask's
# `return jsonify(new_item), 201` on every response).
def create_item(item: Item):
    # `item: Item` tells FastAPI: parse the incoming JSON body, validate it
    # against the Item schema, and hand me a real Python object (item.name,
    # item.description) — not a raw dict like Flask's request.get_json().
    # If validation fails, the function never even runs — FastAPI returns
    # a 422 error automatically.
    global next_id
    new_item = {
        "id": next_id,
        "name": item.name,          # accessed as an attribute, not item["name"]
        "description": item.description,
    }
    items[next_id] = new_item
    next_id += 1
    return new_item
    # Auto-serialized to JSON with status 201 (set above in the decorator).

# PUT — update item
@app.put("/items/{item_id}")
def update_item(item_id: int, item: ItemUpdate):
    # Two parameters: item_id from the URL path, item from the JSON body —
    # FastAPI figures out which is which based on type hints (int vs BaseModel).
    existing = items.get(item_id)
    if not existing:
        raise HTTPException(status_code=404, detail="Item not found")

    if item.name is not None:
        existing["name"] = item.name
        # Only overwrite if the client actually sent a value (not the default None)
    if item.description is not None:
        existing["description"] = item.description

    return existing
'''
Real-world difference: Same PUT-vs-PATCH semantic issue as 
Flask — this is really a PATCH. Production APIs typically 
add a dedicated @app.patch(...) route for partial updates 
and keep @app.put(...) for full replacement.
'''
# DELETE item
@app.delete("/items/{item_id}")
def delete_item(item_id: int):
    item = items.pop(item_id, None)
    if not item:
        raise HTTPException(status_code=404, detail="Item not found")
    return {"message": f"Item {item_id} deleted", "item": item}
"""
Identical logic to Flask's dict.pop() trick — just no jsonify() needed, 
and errors use raise HTTPException instead of return jsonify(...), 404.
"""